function checked = stateflow_contract_gate_v30(raw,hpPorts,energyStart,cfgPorts,model_dt)
%#codegen
% Independent first-law and exact constant-power/temperature contract.
dt=cfgPorts(1); cap=cfgPorts(2); etaC=cfgPorts(5); etaD=cfgPorts(6);
rate=cfgPorts(7); cutoff=cfgPorts(8); C=cfgPorts(9); Ta=cfgPorts(10);
assert(all(isfinite(cfgPorts)) && isfinite(energyStart) && all(isfinite(raw)), 'Nonfinite accepted state/parameters.');
assert(isfinite(model_dt) && dt==model_dt && dt>0 && isfinite(rate*dt), 'Physical interval/decay mismatch.');
assert(cap>=0 && C>0 && rate>=0 && cutoff>=0 && cutoff<=cap && Ta>-273.15 && ...
    cfgPorts(3)>=0 && cfgPorts(4)>=0 && cfgPorts(11)>=0 && etaC>0 && etaC<=1 && etaD>0 && etaD<=1, 'Invalid TES physical domain.');
assert(all(isfinite(hpPorts([1:5 7 8]))) && all(hpPorts([1:5 7 8])>=0), 'Invalid HP port.');
scale=max(1,abs(energyStart)+cap+(hpPorts(2)+cfgPorts(11))*dt);
tol=1e-10*scale; powerTol=tol/max(dt,eps);
assert(isfinite(scale) && isfinite(powerTol), 'Overflow in contract scale.');
assert(energyStart>=0 && energyStart<=cap && raw(8)>=-tol && raw(8)<=cap+tol, 'TES state outside capacity.');
assert(raw(1)==floor(raw(1)) && raw(1)>=0 && raw(1)<=5, 'Undefined mode.');
assert(all(raw([2:6 12])>=-powerTol) && all(raw(7:11)>=-tol), 'Negative dispatch or loss.');
assert(raw(3)<=cfgPorts(3)+powerTol && raw(4)<=cfgPorts(4)+powerTol && raw(5)<=cfgPorts(11)+powerTol, 'TES/boiler power bound.');
assert(raw(3)*raw(4)==0, 'Simultaneous TES ports.');
r=exp(-rate*dt); phi=dt;
if rate>0 && rate*dt>0, phi=-expm1(-rate*dt)/rate; end
P=etaC*raw(3)-raw(4)/etaD;
assert(abs(raw(7)-energyStart*r)<=tol && abs(raw(8)-(energyStart*r+P*phi))<=tol, 'Exact constant-power solution mismatch.');
assert(raw(4)==0 || raw(8)>=cutoff-tol, 'TES discharge crosses delivery cutoff.');
assert(abs(raw(9)-(energyStart+P*dt-raw(8)))<=tol && ...
    abs(raw(10)-(1-etaC)*raw(3)*dt)<=tol && abs(raw(11)-(1/etaD-1)*raw(4)*dt)<=tol, 'TES loss mismatch.');
assert(abs(raw(14)-(Ta+energyStart/C))<=tol/C && abs(raw(15)-(Ta+raw(8)/C))<=tol/C && ...
    abs(raw(16)-max(0,energyStart-cutoff))<=tol && abs(raw(17)-max(0,raw(8)-cutoff))<=tol, 'Temperature/usable-energy mismatch.');
assert(abs(hpPorts(2)-hpPorts(3)-hpPorts(4))*dt<=tol, 'HP first-law failure.');
assert(abs(hpPorts(2)-raw(2)-raw(3))*dt<=tol, 'Unallocated condenser heat.');
assert(abs(hpPorts(1)-raw(2)-raw(4)-raw(5)-raw(6))*dt<=tol, 'Demand closure failure.');
assert(abs(raw(12)-raw(2)-raw(4)-raw(5))*dt<=tol, 'Supplied heat mismatch.');
assert(abs(energyStart+(raw(3)-raw(4))*dt-raw(8)-sum(raw(9:11)))<=tol, 'TES first-law failure.');
residual=(hpPorts(4)+hpPorts(3)+raw(5))*dt+energyStart-raw(12)*dt-raw(8)-sum(raw(9:11));
assert(abs(residual)<=tol && abs(raw(13)-residual)<=tol, 'System first-law or reported residual failure.');
expected=0;
if raw(6)>0, expected=5;
elseif raw(5)>0, expected=4;
elseif raw(4)>0, expected=3;
elseif raw(3)>0, expected=2;
elseif raw(2)>0, expected=1;
end
assert(raw(1)==expected, 'Active state does not match delivered flows.');
if hpPorts(2)>0
    assert(isfinite(hpPorts(6)) && hpPorts(6)>1 && hpPorts(7)==1, 'Invalid operating COP.');
    assert(abs(hpPorts(3)*hpPorts(6)-hpPorts(2))*dt<=tol, 'COP mismatch.');
else
    assert(isnan(hpPorts(6)) && hpPorts(7)==0, 'Off HP must have undefined COP.');
end
checked=raw;
end

function mode = stateflow_choose_mode_v30(hpPorts,energyStart,cfgPorts)
%#codegen
% Highest service condition, using exact uniformly held TES ports.
direct=min(hpPorts(1),hpPorts(2));
st=storage_kernel_v30(energyStart,0,max(0,hpPorts(1)-direct),cfgPorts(1:10));
remaining=max(0,hpPorts(1)-direct-st(2));
if remaining>cfgPorts(11)
    mode=5;
elseif remaining>0
    mode=4;
elseif st(2)>0
    mode=3;
elseif hpPorts(2)>direct
    mode=2;
elseif direct>0
    mode=1;
else
    mode=0;
end
end

function y = stateflow_allocate_v30(mode,hpPorts,energyStart,cfgPorts)
%#codegen
% Active state authorizes charge, discharge, boiler and unmet ports.
dt=cfgPorts(1); direct=0; chargeRequest=0; dischargeRequest=0; gas=0; unmet=0;
if mode>=1, direct=min(hpPorts(1),hpPorts(2)); end
if mode==2, chargeRequest=max(0,hpPorts(2)-direct); end
if mode>=3, dischargeRequest=max(0,hpPorts(1)-direct); end
st=storage_kernel_v30(energyStart,chargeRequest,dischargeRequest,cfgPorts(1:10));
if mode>=4, gas=min(cfgPorts(11),max(0,hpPorts(1)-direct-st(2))); end
if mode==5, unmet=max(0,hpPorts(1)-direct-st(2)-gas); end
supplied=direct+st(2)+gas;
residual=(hpPorts(4)+hpPorts(3)+gas)*dt+energyStart-supplied*dt-st(4)-sum(st(5:7));
y=[mode;direct;st(1);st(2);gas;unmet;st(3);st(4);st(5);st(6);st(7);supplied;residual;st(8:11)];
end

function z = storage_kernel_v30(A,chargeRequest,dischargeRequest,p)
%STORAGE_KERNEL_V30 Exact constant-port, ambient-referenced sensible TES.
%#codegen
% p=[dt_h;capacity_MWh;charge_limit_MW;discharge_limit_MW;etaC;etaD;
%    lambda_per_h;cutoff_MWh;heat_capacity_MWh_per_K;ambient_C].
% z=[charge_MW;discharge_MW;passive_MWh;next_MWh;standing_loss_MWh;
%    charge_loss_MWh;discharge_loss_MWh;start_C;next_C;usable_start_MWh;
%    usable_next_MWh;charge_bound_MW;discharge_bound_MW].
% Ports are constant across the complete following dt interval. Throttle
% before integration; there are no event pulses or clipping at the cutoff.
assert(numel(p)==10 && all(isfinite(p)), 'Invalid TES parameter vector.');
dt=p(1); cap=p(2); etaC=p(5); etaD=p(6); lambda=p(7); cut=p(8);
C=p(9); ambient=p(10);
assert(dt>0 && cap>=0 && all(p(3:4)>=0) && etaC>0 && etaC<=1 && ...
    etaD>0 && etaD<=1 && lambda>=0 && cut>=0 && cut<=cap && ...
    C>0 && ambient>-273.15, 'TES parameters outside physical domain.');
assert(isfinite(A) && A>=0 && A<=cap && isfinite(chargeRequest) && ...
    chargeRequest>=0 && isfinite(dischargeRequest) && dischargeRequest>=0, ...
    'TES state or request outside physical domain.');
assert(chargeRequest==0 || dischargeRequest==0, 'Simultaneous TES requests.');
x=lambda*dt;
assert(isfinite(x), 'Nonfinite continuous rate times interval.');
r=exp(-x); lossFraction=-expm1(-x);
if lambda==0 || x==0
    phi=dt; beta=0;
else
    phi=lossFraction/lambda;
    % beta=dt-phi. Series avoids cancellation near the zero-rate limit.
    if x<1e-4
        beta=dt*x*(0.5-x*(1/6-x*(1/24-x*(1/120-x/720))));
    else
        beta=dt-phi;
    end
end
assert(isfinite(phi) && phi>0 && isfinite(beta) && beta>=0, ...
    'Nonrepresentable exact TES integration coefficients.');
passive=A*r;
chargeBound=((cap-passive)/phi)/etaC;
dischargeBound=(max(0,passive-cut)/phi)*etaD;
assert(isfinite(chargeBound) && isfinite(dischargeBound), ...
    'Nonrepresentable TES port bounds.');
charge=0; discharge=0;
if chargeRequest>0
    charge=min([chargeRequest,p(3),max(0,chargeBound)]);
elseif dischargeRequest>0
    discharge=min([dischargeRequest,p(4),dischargeBound]);
end
power=etaC*charge-discharge/etaD;
next=passive+power*phi;
tol=64*eps(max(1,cap));
assert(isfinite(next) && next>=-tol && next<=cap+tol, ...
    'Exact TES integration violates ambient/capacity bounds.');
% Physical bounds only: correct endpoint roundoff, never force A>=cut.
next=min(cap,max(0,next));
standing=A*lossFraction+power*beta;
chargeLoss=(1-etaC)*charge*dt;
dischargeLoss=(1/etaD-1)*discharge*dt;
assert(isfinite(standing) && standing>=-tol && isfinite(chargeLoss) && ...
    isfinite(dischargeLoss), 'Nonrepresentable TES loss integrals.');
standing=max(0,standing);
startT=ambient+A/C; nextT=ambient+next/C;
assert(isfinite(startT) && isfinite(nextT), 'Nonrepresentable TES temperature.');
z=[charge;discharge;passive;next;standing;chargeLoss;dischargeLoss; ...
    startT;nextT;max(0,A-cut);max(0,next-cut);chargeBound;dischargeBound];
end
